insert into public.products (slug, title, summary, free) values
('finding-my-voice', 'Finding My Voice', 'Make space for what you really think, feel, and need.', true),
('the-boundaries-edit', 'The Boundaries Edit', 'Practice setting limits that protect your time and energy.', false),
('becoming-her', 'Becoming Her', 'Picture the life you want and take one small step toward it.', false);
insert into public.prompts (id, product_slug, position, title, question) values
(1, 'finding-my-voice', 1, 'Start with what you know', 'When do you feel most like yourself? Describe a recent moment.'),
(2, 'finding-my-voice', 2, 'Notice what goes unsaid', 'What have you been holding back? What would help you say it?'),
(3, 'finding-my-voice', 3, 'Practice asking for what you need', 'Write one sentence that communicates a need clearly and kindly.'),
(4, 'finding-my-voice', 4, 'Take one small step', 'Where could you use your voice this week? What will you do first?'),
(5, 'the-boundaries-edit', 1, 'Recognize your limits', 'Describe a recent moment when you agreed to something you wanted to decline.'),
(6, 'the-boundaries-edit', 2, 'Make it clear', 'Write a short, kind response you could use the next time this happens.'),
(7, 'becoming-her', 1, 'Imagine an ordinary day', 'What does an ordinary morning look like in the life you want?'),
(8, 'becoming-her', 2, 'Choose a next step', 'What is one action you can take this week to move toward that vision?');
insert into public.engine_workbooks (slug, title, summary, sample) values ('the-dancer-mindset', 'The Dancer Mindset', 'An original demonstration workbook about showing up, finding your footing, and practicing with intention.', true);
insert into public.engine_module_drafts (id, workbook_slug, content) values
('10000000-0000-4000-8000-000000000001', 'the-dancer-mindset', '{"format":1,"title":"Find your starting position","chapter":"Arriving at practice","chapterOrder":1,"order":1,"blocks":[{"id":"20000000-0000-4000-8000-000000000001","kind":"lesson","body":"Before the music begins, notice where you are today. Your starting position can change from one practice to the next. Take a moment to name what you have available: energy, curiosity, a little time, or simply the willingness to begin.\n\nPick one small thing to pay attention to as you move. It could be your breath, the shift of weight in your feet, or the moment you notice yourself rushing."},{"id":"20000000-0000-4000-8000-000000000002","kind":"reflection","prompt":"What do you notice about how you’re arriving at practice today?"},{"id":"20000000-0000-4000-8000-000000000003","kind":"choice","prompt":"Which cue would help you begin?","options":[{"id":"30000000-0000-4000-8000-000000000001","label":"Exhale before the first count"},{"id":"30000000-0000-4000-8000-000000000002","label":"Feel where my feet meet the floor"},{"id":"30000000-0000-4000-8000-000000000003","label":"Listen for the rhythm before moving"}]},{"id":"20000000-0000-4000-8000-000000000004","kind":"rating","prompt":"How ready do you feel to start a short practice?","max":5,"low":"Need more time","high":"Ready to begin"}]}'::jsonb),
('10000000-0000-4000-8000-000000000002', 'the-dancer-mindset', '{"format":1,"title":"Make room for a second try","chapter":"Arriving at practice","chapterOrder":1,"order":2,"blocks":[{"id":"20000000-0000-4000-8000-000000000005","kind":"lesson","body":"Think of a phrase you lost halfway through. On a second try, give yourself one specific experiment: slow the transition, mark the steps, or return to the last count you remember. When you finish, write down what changed."},{"id":"20000000-0000-4000-8000-000000000006","kind":"reflection","prompt":"Which part of a recent practice would you revisit, and what would you try differently?"}]}'::jsonb),
('10000000-0000-4000-8000-000000000003', 'the-dancer-mindset', '{"format":1,"title":"Plan one repeatable practice","chapter":"Build a rhythm","chapterOrder":2,"order":1,"blocks":[{"id":"20000000-0000-4000-8000-000000000007","kind":"lesson","body":"Choose a practice you could repeat on an ordinary day. Five minutes with a familiar track is enough to start. Decide when and where you’ll do it, and make the first step small enough to take even if your day changes."},{"id":"20000000-0000-4000-8000-000000000008","kind":"goal","prompt":"What practice will you repeat, and what’s the first step you’ll take?"}]}'::jsonb);
insert into public.engine_modules (id, workbook_slug, content, revision) select id, workbook_slug, content, edit_version from public.engine_module_drafts where workbook_slug = 'the-dancer-mindset';
